package com.shatteredpixel.shatteredpixeldungeon.mod;
import com.watabou.utils.Bundle; import com.shatteredpixel.shatteredpixeldungeon.Dungeon; import com.shatteredpixel.shatteredpixeldungeon.items.Item; import com.shatteredpixel.shatteredpixeldungeon.items.potions.Potion; import com.shatteredpixel.shatteredpixeldungeon.items.scrolls.Scroll; import com.shatteredpixel.shatteredpixeldungeon.items.rings.Ring;
public final class ModHooks { public static final class HeroStat { public final String label,value; public HeroStat(String label,String value){this.label=label;this.value=value;} } private ModHooks(){} public static void tick(){if(Dungeon.level!=null&&Dungeon.hero!=null)ModRegistry.tick(Dungeon.level,Dungeon.hero.pos);} public static void heroReadyForInput(){ModRegistry.heroReadyForInput();} public static java.util.List<HeroStat> heroStats(com.shatteredpixel.shatteredpixeldungeon.actors.hero.Hero hero){return ModRegistry.heroStats(hero);} public static void picked(Item i){ModRegistry.picked(i);} public static int gold(int n){return ModRegistry.modifyGold(n);} public static float berserkPowerLoss(float amount,float power,int hp,int ht){return ModRegistry.modifyBerserkPowerLoss(amount,power,hp,ht);} public static float berserkDamageFactor(float damage,float power){return ModRegistry.modifyBerserkDamageFactor(damage,power);} public static int comboRequirement(int requirement,com.shatteredpixel.shatteredpixeldungeon.actors.buffs.Combo.ComboMove move){return ModRegistry.modifyComboRequirement(requirement,move);} public static float comboDamageMultiplier(float multiplier,com.shatteredpixel.shatteredpixeldungeon.actors.buffs.Combo.ComboMove move,int count){return ModRegistry.modifyComboDamageMultiplier(multiplier,move,count);} public static boolean identified(Item i,boolean v){return ModRegistry.identified(i,v);} public static boolean known(Potion i,boolean v){return v;} public static boolean known(Scroll i,boolean v){return v;} public static boolean known(Ring i,boolean v){return v;} public static java.util.ArrayList<Scroll> unstableSpellbookCandidates(Scroll original){return ModRegistry.unstableSpellbookCandidates(original);} public static boolean unstableSpellbookScrollAllowed(Scroll original){return ModRegistry.unstableSpellbookScrollAllowed(original);} public static Item recycleRunestone(Item original,Item result){return ModRegistry.recycleRunestone(original,result);} public static int maxCharges(int calculatedMaximum,int vanillaMaximum){return ModRegistry.modifyMaxCharges(calculatedMaximum,vanillaMaximum);} public static boolean heroDeathDamage(com.shatteredpixel.shatteredpixeldungeon.actors.hero.Hero hero,int damage,Object cause){return com.shatteredpixel.shatteredpixeldungeon.mod.deathreturn.DeathReturnMod.intercept(hero,damage,cause);} public static void store(Bundle b){ModRegistry.store(b);} public static void restore(Bundle b){ModRegistry.restore(b);} }
